def ordinalLiftRowsOperator (μ : C(K, WeakDual 𝕜 E)) {r : ℝ} (hr : 0 ≤ r)
    (hμ : ∀ t, ‖WeakDual.toStrongDual (μ t)‖ ≤ r) : E →L[𝕜] C(K, 𝕜) :=
  (ordinalLiftRowsLinearMap μ).mkContinuous r (ordinalLiftRowsLinearMap_bound μ hr hμ)

